cat >> src/orchestration/tools/registry.test.ts <<'EOF'

describe('ToolRegistry.execute with a static definition', () => {
  it('compiles a static inputSchema once and reuses it across ten execute calls', async () => {
    const registry = new ToolRegistry();
    let reads = 0;
    const tracked = new Proxy(LOCATION_SCHEMA, {
      get(target, key, receiver) {
        reads += 1;
        return Reflect.get(target, key, receiver) as unknown;
      },
    });
    registry.register({name: 'get_weather', description: 'Weather', inputSchema: tracked}, async () => 'sunny');

    const readsAfterRegister = reads;
    for (let i = 0; i < 10; i += 1) await registry.execute('get_weather', {location: 'Berlin'});

    expect({readsAfterRegister: readsAfterRegister > 0, readsDuringExecute: reads - readsAfterRegister}).toEqual({
      readsAfterRegister: true,
      readsDuringExecute: 0,
    });
  });
});
EOF
timeout 300 node --experimental-vm-modules node_modules/.bin/jest src/orchestration/tools/registry.test.ts --coverage=false --silent 2>&1 | tail -6
